

CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "is_admin" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "chapters" ("id" integer primary key autoincrement not null, "bismillah_pre" tinyint(1) not null default '1', "revelation_order" integer not null, "revelation_place" varchar not null, "name_complex" varchar not null, "name_arabic" varchar not null, "name_simple" varchar not null, "pages" varchar, "verses_count" integer not null, "chapter_number" integer not null, "rukus_count" integer, "hizbs_count" integer, "rub_el_hizbs_count" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "verses" ("id" integer primary key autoincrement not null, "chapter_id" integer not null, "verse_number" integer not null, "verse_index" integer not null, "verse_key" varchar not null, "text_uthmani" text not null, "text_indopak" text, "text_imlaei_simple" text, "juz_number" integer not null, "hizb_number" integer not null, "rub_el_hizb_number" integer not null, "sajdah_type" varchar, "sajdah_number" integer, "page_number" integer not null, "image_url" text, "image_width" integer, "verse_root_id" integer, "verse_lemma_id" integer, "verse_stem_id" integer, "text_imlaei" text, "text_uthmani_simple" text, "text_uthmani_tajweed" text, "code_v1" varchar, "code_v2" varchar, "v2_page" integer, "text_qpc_hafs" text, "words_count" integer not null default '0', "text_indopak_nastaleeq" text, "pause_words_count" integer not null default '0', "mushaf_pages_mapping" text not null default '{}', "text_qpc_nastaleeq" text, "ruku_number" integer not null, "surah_ruku_number" integer not null, "manzil_number" integer not null, "text_qpc_nastaleeq_hafs" text, "mushaf_juzs_mapping" text not null default '{}', "created_at" datetime, "updated_at" datetime, foreign key("chapter_id") references "chapters"("id") on delete cascade, foreign key("verse_root_id") references "verse_roots"("id") on delete set null, foreign key("verse_lemma_id") references "verse_lemmas"("id") on delete set null, foreign key("verse_stem_id") references "verse_stems"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "words" ("id" integer primary key autoincrement not null, "verse_id" integer not null, "chapter_id" integer not null, "position" integer not null, "text_uthmani" varchar not null, "text_indopak" varchar, "text_imlaei_simple" varchar, "verse_key" varchar not null, "page_number" integer not null, "class_name" varchar, "line_number" integer not null, "code_dec" integer not null, "code_hex" varchar not null, "code_hex_v3" varchar, "code_dec_v3" integer, "char_type_id" integer, "pause_name" varchar, "audio_url" varchar, "image_blob" text, "image_url" varchar, "token_id" integer, "topic_id" integer, "location" varchar, "char_type_name" varchar, "text_imlaei" varchar, "text_uthmani_simple" varchar, "text_uthmani_tajweed" varchar, "en_transliteration" varchar, "code_v1" varchar, "code_v2" varchar, "v2_page" integer, "line_v2" integer, "text_qpc_hafs" varchar, "text_indopak_nastaleeq" varchar, "text_qpc_nastaleeq" varchar, "text_qpc_nastaleeq_hafs" varchar, "created_at" datetime, "updated_at" datetime, foreign key("verse_id") references "verses"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade, foreign key("char_type_id") references "char_types"("id") on delete set null, foreign key("token_id") references "tokens"("id") on delete set null, foreign key("topic_id") references "topics"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "juzs" ("id" integer primary key autoincrement not null, "juz_number" integer not null, "verse_mapping" text not null, "first_verse_id" integer not null, "last_verse_id" integer not null, "verses_count" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("first_verse_id") references "verses"("id") on delete cascade, foreign key("last_verse_id") references "verses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "hizbs" ("id" integer primary key autoincrement not null, "hizb_number" integer not null, "verse_mapping" text not null, "first_verse_id" integer not null, "last_verse_id" integer not null, "verses_count" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("first_verse_id") references "verses"("id") on delete cascade, foreign key("last_verse_id") references "verses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "languages" ("id" integer primary key autoincrement not null, "name" varchar not null, "iso_code" varchar not null, "native_name" varchar not null, "direction" varchar not null default 'ltr', "es_analyzer_default" varchar, "es_indexes" varchar, "translations_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "resource_contents" ("id" integer primary key autoincrement not null, "approved" tinyint(1) not null default '0', "author_id" integer, "data_source_id" integer, "author_name" varchar, "resource_type_name" varchar not null, "sub_type" varchar not null, "name" varchar not null, "description" text, "cardinality_type" varchar not null default '1_ayah', "language_id" integer not null, "language_name" varchar not null, "slug" varchar not null, "mobile_translation_id" integer, "priority" integer not null default '0', "resource_info" text, "resource_id" varchar, "meta_data" text not null default '{}', "resource_type" varchar not null, "sqlite_db" varchar, "sqlite_db_generated_at" datetime, "records_count" integer not null default '0', "permission_to_host" integer not null default '0', "permission_to_share" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("author_id") references "authors"("id") on delete set null, foreign key("data_source_id") references "data_sources"("id") on delete set null, foreign key("language_id") references "languages"("id") on delete cascade, foreign key("mobile_translation_id") references "resource_contents"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "authors" ("id" integer primary key autoincrement not null, "name" varchar not null, "url" varchar, "resource_contents_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "translations" ("id" integer primary key autoincrement not null, "language_id" integer not null, "text" text not null, "resource_content_id" integer not null, "verse_id" integer not null, "language_name" varchar not null, "resource_name" varchar, "priority" integer not null default '0', "verse_key" varchar not null, "chapter_id" integer not null, "verse_number" integer not null, "juz_number" integer not null, "hizb_number" integer not null, "rub_el_hizb_number" integer not null, "page_number" integer not null, "ruku_number" integer not null, "surah_ruku_number" integer not null, "manzil_number" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("language_id") references "languages"("id") on delete cascade, foreign key("resource_content_id") references "resource_contents"("id") on delete cascade, foreign key("verse_id") references "verses"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tafsirs" ("id" integer primary key autoincrement not null, "verse_id" integer not null, "language_id" integer not null, "text" text not null, "language_name" varchar not null, "resource_content_id" integer not null, "resource_name" varchar, "verse_key" varchar not null, "chapter_id" integer not null, "verse_number" integer not null, "juz_number" integer not null, "hizb_number" integer not null, "rub_el_hizb_number" integer not null, "page_number" integer not null, "group_verse_key_from" varchar, "group_verse_key_to" varchar, "group_verses_count" integer, "group_tafsir_id" integer, "start_verse_id" integer, "end_verse_id" integer, "ruku_number" integer not null, "surah_ruku_number" integer not null, "manzil_number" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("verse_id") references "verses"("id") on delete cascade, foreign key("language_id") references "languages"("id") on delete cascade, foreign key("resource_content_id") references "resource_contents"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade, foreign key("start_verse_id") references "verses"("id") on delete cascade, foreign key("end_verse_id") references "verses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "audio_recitations" ("id" integer primary key autoincrement not null, "name" varchar not null, "arabic_name" varchar, "relative_path" varchar, "format" varchar, "section_id" integer, "description" text, "files_count" integer not null default '0', "resource_content_id" integer, "recitation_style_id" integer, "reciter_id" integer, "approved" tinyint(1) not null default '0', "home" integer not null default '0', "priority" integer not null default '0', "segments_count" integer not null default '0', "files_size" float, "qirat_type_id" integer, "segment_locked" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("section_id") references "audio_sections"("id") on delete set null, foreign key("resource_content_id") references "resource_contents"("id") on delete set null, foreign key("recitation_style_id") references "recitation_styles"("id") on delete set null, foreign key("reciter_id") references "reciters"("id") on delete set null, foreign key("qirat_type_id") references "qirat_types"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "audio_files" ("id" integer primary key autoincrement not null, "verse_id" integer not null, "url" text not null, "duration" integer, "segments" text, "mime_type" varchar, "format" varchar, "is_enabled" tinyint(1) not null default '1', "recitation_id" integer, "verse_key" varchar not null, "chapter_id" integer not null, "verse_number" integer not null, "juz_number" integer not null, "hizb_number" integer not null, "rub_el_hizb_number" integer not null, "page_number" integer not null, "ruku_number" integer not null, "surah_ruku_number" integer not null, "manzil_number" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("verse_id") references "verses"("id") on delete cascade, foreign key("recitation_id") references "recitations"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "audio_segments" ("id" integer primary key autoincrement not null, "audio_file_id" integer not null, "audio_recitation_id" integer, "chapter_id" integer not null, "verse_id" integer not null, "verse_key" varchar not null, "verse_number" integer not null, "timestamp_from" integer not null, "timestamp_to" integer not null, "timestamp_median" integer not null, "segments" text not null default '[]', "duration" integer not null, "duration_ms" integer not null, "percentile" float not null, "silent_duration" integer not null default '0', "relative_segments" text not null default '[]', "relative_silent_duration" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("audio_file_id") references "audio_files"("id") on delete cascade, foreign key("audio_recitation_id") references "audio_recitations"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade, foreign key("verse_id") references "verses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "audio_sections" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "reciters" ("id" integer primary key autoincrement not null, "name" varchar not null, "bio" text, "profile_picture" varchar, "cover_image" varchar, "recitations_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "qirat_types" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "recitations_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "api_clients" ("id" integer primary key autoincrement not null, "name" varchar not null, "api_key" varchar not null, "kalimat_api_key" varchar, "internal_api" tinyint(1) not null default '0', "active" tinyint(1) not null default '1', "request_quota" integer, "requests_count" integer not null default '0', "current_period_requests_count" integer not null default '0', "current_period_ends_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "api_client_request_stats" ("id" integer primary key autoincrement not null, "api_client_id" integer not null, "date" date not null, "requests_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("api_client_id") references "api_clients"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "data_sources" ("id" integer primary key autoincrement not null, "name" varchar not null, "url" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "char_types" ("id" integer primary key autoincrement not null, "name" varchar not null, "parent_id" integer, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "tokens" ("id" integer primary key autoincrement not null, "text_uthmani" varchar not null, "text_imlaei_simple" varchar, "text_indopak" varchar, "text_imlaei" varchar, "text_uthmani_tajweed" varchar, "text" text, "resource_content_id" integer, "record_id" integer, "record_type" varchar, "uniq_token_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("resource_content_id") references "resource_contents"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "roots" ("id" integer primary key autoincrement not null, "value" varchar not null, "text_clean" varchar, "text_uthmani" varchar, "english_trilateral" varchar, "arabic_trilateral" varchar, "en_translations" text not null default '[]', "ur_translations" text not null default '[]', "dictionary_image_path" varchar, "words_count" integer not null default '0', "uniq_words_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "verse_roots" ("id" integer primary key autoincrement not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "verse_lemmas" ("id" integer primary key autoincrement not null, "text_madani" varchar, "text_clean" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "verse_stems" ("id" integer primary key autoincrement not null, "text_madani" varchar, "text_clean" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "quran_bookmarks" ("id" integer primary key autoincrement not null, "user_id" integer not null, "chapter_id" integer not null, "verse_number" integer not null, "verse_id" varchar not null, "verse_data" text, "notes" text, "edition" varchar not null default 'en.sahih', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE IF NOT EXISTS "collections" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "description" text, "color" varchar not null default '#3b82f6', "is_public" tinyint(1) not null default '0', "slug" varchar not null, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "collection_verse" ("id" integer primary key autoincrement not null, "collection_id" integer not null, "verse_id" integer not null, "display_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("collection_id") references "collections"("id") on delete cascade, foreign key("verse_id") references "verses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "resource_types" ("id" integer primary key autoincrement not null, "slug" varchar not null, "name" varchar not null, "display_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_verse_resources" (
                id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT NOT NULL,
                user_id INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
                verse_id INTEGER NOT NULL REFERENCES "verses"("id") ON DELETE CASCADE,
                resource_type_id INTEGER NOT NULL REFERENCES "resource_types"("id") ON DELETE RESTRICT,
                resource_url VARCHAR NOT NULL,
                comment TEXT,
                status VARCHAR NOT NULL DEFAULT "pending",
                created_at DATETIME,
                updated_at DATETIME
            );
CREATE TABLE IF NOT EXISTS "surah_infos" ("id" integer primary key autoincrement not null, "surah_number" integer not null, "surah_name" varchar not null, "text" text, "short_text" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_chapter_resources" ("id" integer primary key autoincrement not null, "user_id" integer not null, "chapter_id" integer not null, "resource_type_id" integer not null, "resource_url" varchar not null, "comment" text, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("chapter_id") references "chapters"("id") on delete cascade, foreign key("resource_type_id") references "resource_types"("id") on delete restrict);
