INSERT INTO cache VALUES('fromquran-cache-quran.db.verses.1.1.10.en.sahih','a:7:{i:0;a:11:{s:2:"id";i:1;s:11:"verseNumber";i:1;s:4:"text";s:73:"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ";s:11:"translation";s:68:"In the name of Allah, the Entirely Merciful, the Especially Merciful";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:1;s:13:"resourceCount";i:2;}i:1;a:11:{s:2:"id";i:2;s:11:"verseNumber";i:2;s:4:"text";s:71:"ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ";s:11:"translation";s:50:"[All] praise is [due] to Allah, Lord of the worlds";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}i:2;a:11:{s:2:"id";i:3;s:11:"verseNumber";i:3;s:4:"text";s:45:"ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ";s:11:"translation";s:46:"The Entirely Merciful, the Especially Merciful";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}i:3;a:11:{s:2:"id";i:4;s:11:"verseNumber";i:4;s:4:"text";s:44:"مَٰلِكِ يَوۡمِ ٱلدِّينِ";s:11:"translation";s:34:"Sovereign of the Day of Recompense";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}i:4;a:11:{s:2:"id";i:5;s:11:"verseNumber";i:5;s:4:"text";s:77:"إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ";s:11:"translation";s:44:"It is You we worship and You we ask for help";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}i:5;a:11:{s:2:"id";i:6;s:11:"verseNumber";i:6;s:4:"text";s:66:"ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ";s:11:"translation";s:29:"Guide us to the straight path";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}i:6;a:11:{s:2:"id";i:7;s:11:"verseNumber";i:7;s:4:"text";s:172:"صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ";s:11:"translation";s:121:"The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray";s:9:"juzNumber";i:1;s:10:"pageNumber";i:1;s:11:"hizbQuarter";i:4;s:5:"sajda";b:0;s:8:"audioUrl";N;s:12:"hasResources";b:0;s:13:"resourceCount";i:0;}}',1768042661);
