INSERT INTO verses VALUES(2238,18,98,2238,'18:98','قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,189,10,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2239,18,99,2239,'18:99','۞وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعٗا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,189,10,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2240,18,100,2240,'18:100','وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,190,10,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2241,18,101,2241,'18:101','ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,190,11,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
