INSERT INTO verses VALUES(2244,18,104,2244,'18:104','ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,190,11,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2245,18,105,2245,'18:105','أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,190,11,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2246,18,106,2246,'18:106','ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا',NULL,NULL,4,25,100,NULL,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,190,11,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
