INSERT INTO verses VALUES(2254,19,4,2254,'19:4','قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,190,1,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
