INSERT INTO verses VALUES(2256,19,6,2256,'19:6','يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,190,1,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2257,19,7,2257,'19:7','يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,190,1,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
