INSERT INTO verses VALUES(2261,19,11,2261,'19:11','فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2262,19,12,2262,'19:12','يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2263,19,13,2263,'19:13','وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2264,19,14,2264,'19:14','وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2265,19,15,2265,'19:15','وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2266,19,16,2266,'19:16','وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2267,19,17,2267,'19:17','فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2268,19,18,2268,'19:18','قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2269,19,19,2269,'19:19','قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,191,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2270,19,20,2270,'19:20','قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,192,2,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2271,19,21,2271,'19:21','قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2272,19,22,2272,'19:22','۞فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2273,19,23,2273,'19:23','فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2274,19,24,2274,'19:24','فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2275,19,25,2275,'19:25','وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2276,19,26,2276,'19:26','فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2277,19,27,2277,'19:27','فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2278,19,28,2278,'19:28','يَـٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2279,19,29,2279,'19:29','فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,192,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2280,19,30,2280,'19:30','قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,193,3,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2281,19,31,2281,'19:31','وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2282,19,32,2282,'19:32','وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2283,19,33,2283,'19:33','وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2284,19,34,2284,'19:34','ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِي فِيهِ يَمۡتَرُونَ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2285,19,35,2285,'19:35','مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2286,19,36,2286,'19:36','وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2287,19,37,2287,'19:37','فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2288,19,38,2288,'19:38','أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلٖ مُّبِينٖ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2289,19,39,2289,'19:39','وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,193,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2290,19,40,2290,'19:40','إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,194,4,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2291,19,41,2291,'19:41','وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2292,19,42,2292,'19:42','إِذۡ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2293,19,43,2293,'19:43','يَـٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2294,19,44,2294,'19:44','يَـٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2295,19,45,2295,'19:45','يَـٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2296,19,46,2296,'19:46','قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَـٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2297,19,47,2297,'19:47','قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2298,19,48,2298,'19:48','وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2299,19,49,2299,'19:49','فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,194,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2300,19,50,2300,'19:50','وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,195,5,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2301,19,51,2301,'19:51','وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2302,19,52,2302,'19:52','وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2303,19,53,2303,'19:53','وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2304,19,54,2304,'19:54','وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2305,19,55,2305,'19:55','وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2306,19,56,2306,'19:56','وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2307,19,57,2307,'19:57','وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2308,19,58,2308,'19:58','أُوْلَـٰٓئِكَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحٖ وَمِن ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَـٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا۩',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,29,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2309,19,59,2309,'19:59','۞فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,195,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2310,19,60,2310,'19:60','إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ شَيۡـٔٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,196,6,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2311,19,61,2311,'19:61','جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ بِٱلۡغَيۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2312,19,62,2312,'19:62','لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗاۖ وَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2313,19,63,2313,'19:63','تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2314,19,64,2314,'19:64','وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2315,19,65,2315,'19:65','رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2316,19,66,2316,'19:66','وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2317,19,67,2317,'19:67','أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـٔٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2318,19,68,2318,'19:68','فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2319,19,69,2319,'19:69','ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,196,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2320,19,70,2320,'19:70','ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,197,7,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2321,19,71,2321,'19:71','وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2322,19,72,2322,'19:72','ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّـٰلِمِينَ فِيهَا جِثِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2323,19,73,2323,'19:73','وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2324,19,74,2324,'19:74','وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2325,19,75,2325,'19:75','قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2326,19,76,2326,'19:76','وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2327,19,77,2327,'19:77','أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالٗا وَوَلَدًا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2328,19,78,2328,'19:78','أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:01','2025-12-21 16:16:01');
INSERT INTO verses VALUES(2329,19,79,2329,'19:79','كَلَّاۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,197,8,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2330,19,80,2330,'19:80','وَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,198,8,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2331,19,81,2331,'19:81','وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,198,9,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2332,19,82,2332,'19:82','كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا',NULL,NULL,4,25,100,NULL,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,198,9,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
