INSERT INTO verses VALUES(2386,20,38,2386,'20:38','إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,203,4,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2387,20,39,2387,'20:39','أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,203,4,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2388,20,40,2388,'20:40','إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34,NULL,0,'{}',NULL,204,4,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2389,20,41,2389,'20:41','وَٱصۡطَنَعۡتُكَ لِنَفۡسِي',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2390,20,42,2390,'20:42','ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2391,20,43,2391,'20:43','ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2392,20,44,2392,'20:44','فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2393,20,45,2393,'20:45','قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2394,20,46,2394,'20:46','قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2395,20,47,2395,'20:47','فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2396,20,48,2396,'20:48','إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ',NULL,NULL,4,25,100,NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,204,5,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
