INSERT INTO verses VALUES(2675,23,2,2675,'23:2','ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,230,1,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
