INSERT INTO verses VALUES(2680,23,7,2680,'23:7','فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,230,1,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
INSERT INTO verses VALUES(2681,23,8,2681,'23:8','وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,230,1,4,NULL,'{}','2025-12-21 16:16:02','2025-12-21 16:16:02');
