INSERT INTO verses VALUES(2685,23,12,2685,'23:12','وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,231,2,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2686,23,13,2686,'23:13','ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,231,2,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2687,23,14,2687,'23:14','ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,231,2,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2688,23,15,2688,'23:15','ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,231,2,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
