INSERT INTO verses VALUES(2708,23,35,2708,'23:35','أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,233,4,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
