INSERT INTO verses VALUES(2737,23,64,2737,'23:64','حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,236,7,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2738,23,65,2738,'23:65','لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,236,7,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2739,23,66,2739,'23:66','قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,236,7,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
