INSERT INTO verses VALUES(2772,23,99,2772,'23:99','حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,239,10,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2773,23,100,2773,'23:100','لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,240,10,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2774,23,101,2774,'23:101','فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2775,23,102,2775,'23:102','فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2776,23,103,2776,'23:103','وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2777,23,104,2777,'23:104','تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2778,23,105,2778,'23:105','أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2779,23,106,2779,'23:106','قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2780,23,107,2780,'23:107','رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ',NULL,NULL,5,33,132,NULL,NULL,40,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,240,11,4,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
