INSERT INTO verses VALUES(2925,25,70,2925,'25:70','إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا',NULL,NULL,6,41,164,NULL,NULL,44,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,257,7,5,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2926,25,71,2926,'25:71','وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا',NULL,NULL,6,41,164,NULL,NULL,44,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,257,8,5,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
INSERT INTO verses VALUES(2927,25,72,2927,'25:72','وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا',NULL,NULL,6,41,164,NULL,NULL,44,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,257,8,5,NULL,'{}','2025-12-21 16:16:03','2025-12-21 16:16:03');
