INSERT INTO verses VALUES(3164,27,5,3164,'27:5','أُوْلَـٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ وَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ',NULL,NULL,6,41,164,NULL,NULL,48,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,270,1,5,NULL,'{}','2025-12-21 16:16:04','2025-12-21 16:16:04');
