INSERT INTO verses VALUES(3708,36,3,3708,'36:3','إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3709,36,4,3709,'36:4','عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3710,36,5,3710,'36:5','تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3711,36,6,3711,'36:6','لِتُنذِرَ قَوۡمٗا مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3712,36,7,3712,'36:7','لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِنُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3713,36,8,3713,'36:8','إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلٗا فَهِيَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3714,36,9,3714,'36:9','وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدّٗا وَمِنۡ خَلۡفِهِمۡ سَدّٗا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,360,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3715,36,10,3715,'36:10','وَسَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,361,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3716,36,11,3716,'36:11','إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3717,36,12,3717,'36:12','إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3718,36,13,3718,'36:13','وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3719,36,14,3719,'36:14','إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3720,36,15,3720,'36:15','قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3721,36,16,3721,'36:16','قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3722,36,17,3722,'36:17','وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3723,36,18,3723,'36:18','قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3724,36,19,3724,'36:19','قَالُواْ طَـٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,361,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3725,36,20,3725,'36:20','وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,362,2,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3726,36,21,3726,'36:21','ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3727,36,22,3727,'36:22','وَمَالِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3728,36,23,3728,'36:23','ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرّٖ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـٔٗا وَلَا يُنقِذُونِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3729,36,24,3729,'36:24','إِنِّيٓ إِذٗا لَّفِي ضَلَٰلٖ مُّبِينٍ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3730,36,25,3730,'36:25','إِنِّيٓ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3731,36,26,3731,'36:26','قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3732,36,27,3732,'36:27','بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3733,36,28,3733,'36:28','۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3734,36,29,3734,'36:29','إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ خَٰمِدُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,362,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3735,36,30,3735,'36:30','يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,363,3,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3736,36,31,3736,'36:31','أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3737,36,32,3737,'36:32','وَإِن كُلّٞ لَّمَّا جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3738,36,33,3738,'36:33','وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3739,36,34,3739,'36:34','وَجَعَلۡنَا فِيهَا جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3740,36,35,3740,'36:35','لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3741,36,36,3741,'36:36','سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3742,36,37,3742,'36:37','وَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3743,36,38,3743,'36:38','وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3744,36,39,3744,'36:39','وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,363,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3745,36,40,3745,'36:40','لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,364,4,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3746,36,41,3746,'36:41','وَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3747,36,42,3747,'36:42','وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3748,36,43,3748,'36:43','وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُنقَذُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3749,36,44,3749,'36:44','إِلَّا رَحۡمَةٗ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٖ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3750,36,45,3750,'36:45','وَإِذَا قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3751,36,46,3751,'36:46','وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3752,36,47,3752,'36:47','وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ مُّبِينٖ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,24,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3753,36,48,3753,'36:48','وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3754,36,49,3754,'36:49','مَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,364,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3755,36,50,3755,'36:50','فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,365,5,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3756,36,51,3756,'36:51','وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3757,36,52,3757,'36:52','قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3758,36,53,3758,'36:53','إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3759,36,54,3759,'36:54','فَٱلۡيَوۡمَ لَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3760,36,55,3760,'36:55','إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3761,36,56,3761,'36:56','هُمۡ وَأَزۡوَٰجُهُمۡ فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3762,36,57,3762,'36:57','لَهُمۡ فِيهَا فَٰكِهَةٞ وَلَهُم مَّا يَدَّعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3763,36,58,3763,'36:58','سَلَٰمٞ قَوۡلٗا مِّن رَّبّٖ رَّحِيمٖ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3764,36,59,3764,'36:59','وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,365,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3765,36,60,3765,'36:60','۞أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,366,6,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3766,36,61,3766,'36:61','وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3767,36,62,3767,'36:62','وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلّٗا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3768,36,63,3768,'36:63','هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3769,36,64,3769,'36:64','ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3770,36,65,3770,'36:65','ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3771,36,66,3771,'36:66','وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3772,36,67,3772,'36:67','وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيّٗا وَلَا يَرۡجِعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3773,36,68,3773,'36:68','وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3774,36,69,3774,'36:69','وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,366,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3775,36,70,3775,'36:70','لِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,367,7,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3776,36,71,3776,'36:71','أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3777,36,72,3777,'36:72','وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3778,36,73,3778,'36:73','وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3779,36,74,3779,'36:74','وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لَّعَلَّهُمۡ يُنصَرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3780,36,75,3780,'36:75','لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندٞ مُّحۡضَرُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3781,36,76,3781,'36:76','فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3782,36,77,3782,'36:77','أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3783,36,78,3783,'36:78','وَضَرَبَ لَنَا مَثَلٗا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمٞ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3784,36,79,3784,'36:79','قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,367,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3785,36,80,3785,'36:80','ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,368,8,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
