INSERT INTO verses VALUES(3787,36,82,3787,'36:82','إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,368,9,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(3788,36,83,3788,'36:83','فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ',NULL,NULL,8,57,228,NULL,NULL,66,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,368,9,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
