INSERT INTO verses VALUES(3793,37,5,3793,'37:5','رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ',NULL,NULL,9,65,260,NULL,NULL,68,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,370,1,5,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
