INSERT INTO verses VALUES(4008,38,38,4008,'38:38','وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,383,4,6,NULL,'{}','2025-12-21 16:16:06','2025-12-21 16:16:06');
INSERT INTO verses VALUES(4009,38,39,4009,'38:39','هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,383,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4010,38,40,4010,'38:40','وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,384,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4011,38,41,4011,'38:41','وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4012,38,42,4012,'38:42','ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4013,38,43,4013,'38:43','وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4014,38,44,4014,'38:44','وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4015,38,45,4015,'38:45','وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4016,38,46,4016,'38:46','إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى ٱلدَّارِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
