INSERT INTO verses VALUES(4018,38,48,4018,'38:48','وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4019,38,49,4019,'38:49','هَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,384,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4020,38,50,4020,'38:50','جَنَّـٰتِ عَدۡنٖ مُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,385,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4021,38,51,4021,'38:51','مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةٖ كَثِيرَةٖ وَشَرَابٖ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,385,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4022,38,52,4022,'38:52','۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,385,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
