INSERT INTO verses VALUES(4029,38,59,4029,'38:59','هَٰذَا فَوۡجٞ مُّقۡتَحِمٞ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,385,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4030,38,60,4030,'38:60','قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,386,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4031,38,61,4031,'38:61','قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابٗا ضِعۡفٗا فِي ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,386,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4032,38,62,4032,'38:62','وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,386,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
