INSERT INTO verses VALUES(4054,38,84,4054,'38:84','قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,388,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4055,38,85,4055,'38:85','لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِينَ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,388,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4056,38,86,4056,'38:86','قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,388,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
