INSERT INTO verses VALUES(4058,38,88,4058,'38:88','وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ',NULL,NULL,9,65,260,NULL,NULL,70,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,388,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4059,39,1,4059,'39:1','تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4060,39,2,4060,'39:2','إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4061,39,3,4061,'39:3','أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,33,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4062,39,4,4062,'39:4','لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4063,39,5,4063,'39:5','خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّـٰرُ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4064,39,6,4064,'39:6','خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,36,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4065,39,7,4065,'39:7','إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,31,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4066,39,8,4066,'39:8','۞وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4067,39,9,4067,'39:9','أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,24,NULL,0,'{}',NULL,390,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4068,39,10,4068,'39:10','قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,391,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4069,39,11,4069,'39:11','قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4070,39,12,4070,'39:12','وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4071,39,13,4071,'39:13','قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4072,39,14,4072,'39:14','قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4073,39,15,4073,'39:15','فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4074,39,16,4074,'39:16','لَهُم مِّن فَوۡقِهِمۡ ظُلَلٞ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلٞۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4075,39,17,4075,'39:17','وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّـٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4076,39,18,4076,'39:18','ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَـٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4077,39,19,4077,'39:19','أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,391,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4078,39,20,4078,'39:20','لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفٞ مِّن فَوۡقِهَا غُرَفٞ مَّبۡنِيَّةٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,392,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4079,39,21,4079,'39:21','أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,31,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4080,39,22,4080,'39:22','أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ فَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4081,39,23,4081,'39:23','ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4082,39,24,4082,'39:24','أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّـٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4083,39,25,4083,'39:25','كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4084,39,26,4084,'39:26','فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4085,39,27,4085,'39:27','وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4086,39,28,4086,'39:28','قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4087,39,29,4087,'39:29','ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,392,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4088,39,30,4088,'39:30','إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,393,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4089,39,31,4089,'39:31','ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4090,39,32,4090,'39:32','۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4091,39,33,4091,'39:33','وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4092,39,34,4092,'39:34','لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4093,39,35,4093,'39:35','لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4094,39,36,4094,'39:36','أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4095,39,37,4095,'39:37','وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4096,39,38,4096,'39:38','وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,36,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4097,39,39,4097,'39:39','قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,393,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4098,39,40,4098,'39:40','مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,394,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4099,39,41,4099,'39:41','إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4100,39,42,4100,'39:42','ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,26,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4101,39,43,4101,'39:43','أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4102,39,44,4102,'39:44','قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4103,39,45,4103,'39:45','وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4104,39,46,4104,'39:46','قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4105,39,47,4105,'39:47','وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4106,39,48,4106,'39:48','وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4107,39,49,4107,'39:49','فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,394,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4108,39,50,4108,'39:50','قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,395,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4109,39,51,4109,'39:51','فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَـٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4110,39,52,4110,'39:52','أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4111,39,53,4111,'39:53','۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4112,39,54,4112,'39:54','وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4113,39,55,4113,'39:55','وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ بَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4114,39,56,4114,'39:56','أَن تَقُولَ نَفۡسٞ يَٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4115,39,57,4115,'39:57','أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4116,39,58,4116,'39:58','أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4117,39,59,4117,'39:59','بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,395,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4118,39,60,4118,'39:60','وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,396,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4119,39,61,4119,'39:61','وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4120,39,62,4120,'39:62','ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4121,39,63,4121,'39:63','لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4122,39,64,4122,'39:64','قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4123,39,65,4123,'39:65','وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4124,39,66,4124,'39:66','بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّـٰكِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4125,39,67,4125,'39:67','وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطۡوِيَّـٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4126,39,68,4126,'39:68','وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامٞ يَنظُرُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4127,39,69,4127,'39:69','وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,396,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4128,39,70,4128,'39:70','وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,397,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4129,39,71,4129,'39:71','وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34,NULL,0,'{}',NULL,397,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4130,39,72,4130,'39:72','قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,397,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4131,39,73,4131,'39:73','وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,397,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4132,39,74,4132,'39:74','وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,397,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4133,39,75,4133,'39:75','وَتَرَى ٱلۡمَلَـٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ',NULL,NULL,9,65,260,NULL,NULL,72,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,397,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4134,40,1,4134,'40:1','حمٓ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4135,40,2,4135,'40:2','تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4136,40,3,4136,'40:3','غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4137,40,4,4137,'40:4','مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4138,40,5,4138,'40:5','كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4139,40,6,4139,'40:6','وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4140,40,7,4140,'40:7','ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4141,40,8,4141,'40:8','رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4142,40,9,4142,'40:9','وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,400,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4143,40,10,4143,'40:10','إِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,401,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4144,40,11,4144,'40:11','قَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4145,40,12,4145,'40:12','ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِيِّ ٱلۡكَبِيرِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4146,40,13,4146,'40:13','هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزۡقٗاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4147,40,14,4147,'40:14','فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4148,40,15,4148,'40:15','رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4149,40,16,4149,'40:16','يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءٞۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4150,40,17,4150,'40:17','ٱلۡيَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡيَوۡمَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4151,40,18,4151,'40:18','وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ مَا لِلظَّـٰلِمِينَ مِنۡ حَمِيمٖ وَلَا شَفِيعٖ يُطَاعُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4152,40,19,4152,'40:19','يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,401,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4153,40,20,4153,'40:20','وَٱللَّهُ يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ بِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,402,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4154,40,21,4154,'40:21','۞أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4155,40,22,4155,'40:22','ذَٰلِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4156,40,23,4156,'40:23','وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4157,40,24,4157,'40:24','إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4158,40,25,4158,'40:25','فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4159,40,26,4159,'40:26','وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4160,40,27,4160,'40:27','وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4161,40,28,4161,'40:28','وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,39,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4162,40,29,4162,'40:29','يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,26,NULL,0,'{}',NULL,402,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4163,40,30,4163,'40:30','وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,403,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4164,40,31,4164,'40:31','مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4165,40,32,4165,'40:32','وَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4166,40,33,4166,'40:33','يَوۡمَ تُوَلُّونَ مُدۡبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4167,40,34,4167,'40:34','وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4168,40,35,4168,'40:35','ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرٖ جَبَّارٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4169,40,36,4169,'40:36','وَقَالَ فِرۡعَوۡنُ يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحٗا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4170,40,37,4170,'40:37','أَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4171,40,38,4171,'40:38','وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4172,40,39,4172,'40:39','يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,403,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4173,40,40,4173,'40:40','مَنۡ عَمِلَ سَيِّئَةٗ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,404,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4174,40,41,4174,'40:41','۞وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4175,40,42,4175,'40:42','تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّـٰرِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4176,40,43,4176,'40:43','لَا جَرَمَ أَنَّمَا تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةٞ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4177,40,44,4177,'40:44','فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4178,40,45,4178,'40:45','فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4179,40,46,4179,'40:46','ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4180,40,47,4180,'40:47','وَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4181,40,48,4181,'40:48','قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4182,40,49,4182,'40:49','وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,404,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4183,40,50,4183,'40:50','قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَـٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,405,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4184,40,51,4184,'40:51','إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4185,40,52,4185,'40:52','يَوۡمَ لَا يَنفَعُ ٱلظَّـٰلِمِينَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4186,40,53,4186,'40:53','وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡكِتَٰبَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4187,40,54,4187,'40:54','هُدٗى وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4188,40,55,4188,'40:55','فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4189,40,56,4189,'40:56','إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4190,40,57,4190,'40:57','لَخَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4191,40,58,4191,'40:58','وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4192,40,59,4192,'40:59','إِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞ لَّا رَيۡبَ فِيهَا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,405,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4193,40,60,4193,'40:60','وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,406,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4194,40,61,4194,'40:61','ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4195,40,62,4195,'40:62','ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ خَٰلِقُ كُلِّ شَيۡءٖ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4196,40,63,4196,'40:63','كَذَٰلِكَ يُؤۡفَكُ ٱلَّذِينَ كَانُواْ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4197,40,64,4197,'40:64','ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4198,40,65,4198,'40:65','هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4199,40,66,4199,'40:66','۞قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ ٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4200,40,67,4200,'40:67','هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ يُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى وَلَعَلَّكُمۡ تَعۡقِلُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4201,40,68,4201,'40:68','هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4202,40,69,4202,'40:69','أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,406,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4203,40,70,4203,'40:70','ٱلَّذِينَ كَذَّبُواْ بِٱلۡكِتَٰبِ وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,407,7,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4204,40,71,4204,'40:71','إِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4205,40,72,4205,'40:72','فِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4206,40,73,4206,'40:73','ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4207,40,74,4207,'40:74','مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4208,40,75,4208,'40:75','ذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4209,40,76,4209,'40:76','ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4210,40,77,4210,'40:77','فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4211,40,78,4211,'40:78','وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,32,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4212,40,79,4212,'40:79','ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,407,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4213,40,80,4213,'40:80','وَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,408,8,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4214,40,81,4214,'40:81','وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,408,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4215,40,82,4215,'40:82','أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,408,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4216,40,83,4216,'40:83','فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,408,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4217,40,84,4217,'40:84','فَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,408,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4218,40,85,4218,'40:85','فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ',NULL,NULL,9,65,260,NULL,NULL,74,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,408,9,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4219,41,1,4219,'41:1','حمٓ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4220,41,2,4220,'41:2','تَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4221,41,3,4221,'41:3','كِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ قُرۡءَانًا عَرَبِيّٗا لِّقَوۡمٖ يَعۡلَمُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4222,41,4,4222,'41:4','بَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4223,41,5,4223,'41:5','وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4224,41,6,4224,'41:6','قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4225,41,7,4225,'41:7','ٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4226,41,8,4226,'41:8','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4227,41,9,4227,'41:9','۞قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,410,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4228,41,10,4228,'41:10','وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,411,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4229,41,11,4229,'41:11','ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4230,41,12,4230,'41:12','فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَاۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَحِفۡظٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4231,41,13,4231,'41:13','فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ عَادٖ وَثَمُودَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4232,41,14,4232,'41:14','إِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4233,41,15,4233,'41:15','فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4234,41,16,4234,'41:16','فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4235,41,17,4235,'41:17','وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُواْ يَكۡسِبُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4236,41,18,4236,'41:18','وَنَجَّيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4237,41,19,4237,'41:19','وَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,411,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4238,41,20,4238,'41:20','حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,412,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4239,41,21,4239,'41:21','وَقَالُواْ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَيۡنَاۖ قَالُوٓاْ أَنطَقَنَا ٱللَّهُ ٱلَّذِيٓ أَنطَقَ كُلَّ شَيۡءٖۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةٖ وَإِلَيۡهِ تُرۡجَعُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4240,41,22,4240,'41:22','وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرٗا مِّمَّا تَعۡمَلُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4241,41,23,4241,'41:23','وَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4242,41,24,4242,'41:24','فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوٗى لَّهُمۡۖ وَإِن يَسۡتَعۡتِبُواْ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4243,41,25,4243,'41:25','۞وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4244,41,26,4244,'41:26','وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4245,41,27,4245,'41:27','فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابٗا شَدِيدٗا وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4246,41,28,4246,'41:28','ذَٰلِكَ جَزَآءُ أَعۡدَآءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4247,41,29,4247,'41:29','وَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,412,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4248,41,30,4248,'41:30','إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ ٱلَّتِي كُنتُمۡ تُوعَدُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,413,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4249,41,31,4249,'41:31','نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّعُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4250,41,32,4250,'41:32','نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4251,41,33,4251,'41:33','وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4252,41,34,4252,'41:34','وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4253,41,35,4253,'41:35','وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4254,41,36,4254,'41:36','وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4255,41,37,4255,'41:37','وَمِنۡ ءَايَٰتِهِ ٱلَّيۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4256,41,38,4256,'41:38','فَإِنِ ٱسۡتَكۡبَرُواْ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيۡلِ وَٱلنَّهَارِ وَهُمۡ لَا يَسۡـَٔمُونَ۩',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4257,41,39,4257,'41:39','وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,413,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4258,41,40,4258,'41:40','إِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ أَفَمَن يُلۡقَىٰ فِي ٱلنَّارِ خَيۡرٌ أَم مَّن يَأۡتِيٓ ءَامِنٗا يَوۡمَ ٱلۡقِيَٰمَةِۚ ٱعۡمَلُواْ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٌ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,26,NULL,0,'{}',NULL,414,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4259,41,41,4259,'41:41','إِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4260,41,42,4260,'41:42','لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِيلٞ مِّنۡ حَكِيمٍ حَمِيدٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4261,41,43,4261,'41:43','مَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4262,41,44,4262,'41:44','وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيّٗا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ ءَا۬عۡجَمِيّٞ وَعَرَبِيّٞۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ وَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَـٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4263,41,45,4263,'41:45','وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4264,41,46,4264,'41:46','مَّنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4265,41,47,4265,'41:47','۞إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتٖ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ شُرَكَآءِي قَالُوٓاْ ءَاذَنَّـٰكَ مَامِنَّا مِن شَهِيدٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4266,41,48,4266,'41:48','وَضَلَّ عَنۡهُم مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4267,41,49,4267,'41:49','لَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,414,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4268,41,50,4268,'41:50','وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُم مِّنۡ عَذَابٍ غَلِيظٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,32,NULL,0,'{}',NULL,415,5,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4269,41,51,4269,'41:51','وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,415,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4270,41,52,4270,'41:52','قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدٖ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,415,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4271,41,53,4271,'41:53','سَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,415,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4272,41,54,4272,'41:54','أَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءٖ مُّحِيطُۢ',NULL,NULL,9,65,260,NULL,NULL,76,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,415,6,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4273,42,1,4273,'42:1','حمٓ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4274,42,2,4274,'42:2','عٓسٓقٓ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4275,42,3,4275,'42:3','كَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4276,42,4,4276,'42:4','لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4277,42,5,4277,'42:5','تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَـٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4278,42,6,4278,'42:6','وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4279,42,7,4279,'42:7','وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ قُرۡءَانًا عَرَبِيّٗا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ يَوۡمَ ٱلۡجَمۡعِ لَا رَيۡبَ فِيهِۚ فَرِيقٞ فِي ٱلۡجَنَّةِ وَفَرِيقٞ فِي ٱلسَّعِيرِ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4280,42,8,4280,'42:8','وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِيّٖ وَلَا نَصِيرٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4281,42,9,4281,'42:9','أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,420,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4282,42,10,4282,'42:10','وَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ ذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,421,1,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4283,42,11,4283,'42:11','فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4284,42,12,4284,'42:12','لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4285,42,13,4285,'42:13','۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,38,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4286,42,14,4286,'42:14','وَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰٓ أَجَلٖ مُّسَمّٗى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ أُورِثُواْ ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4287,42,15,4287,'42:15','فَلِذَٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٖۖ وَأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ لَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4288,42,16,4288,'42:16','وَٱلَّذِينَ يُحَآجُّونَ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَبٞ وَلَهُمۡ عَذَابٞ شَدِيدٌ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4289,42,17,4289,'42:17','ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4290,42,18,4290,'42:18','يَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِي ٱلسَّاعَةِ لَفِي ضَلَٰلِۭ بَعِيدٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4291,42,19,4291,'42:19','ٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,421,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4292,42,20,4292,'42:20','مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن نَّصِيبٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,422,2,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4293,42,21,4293,'42:21','أَمۡ لَهُمۡ شُرَكَـٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ٱلدِّينِ مَا لَمۡ يَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِيَ بَيۡنَهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4294,42,22,4294,'42:22','تَرَى ٱلظَّـٰلِمِينَ مُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,24,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4295,42,23,4295,'42:23','ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورٞ شَكُورٌ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,29,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4296,42,24,4296,'42:24','أَمۡ يَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4297,42,25,4297,'42:25','وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4298,42,26,4298,'42:26','وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابٞ شَدِيدٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4299,42,27,4299,'42:27','۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4300,42,28,4300,'42:28','وَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4301,42,29,4301,'42:29','وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٖۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,422,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4302,42,30,4302,'42:30','وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,423,3,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4303,42,31,4303,'42:31','وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:07','2025-12-21 16:16:07');
INSERT INTO verses VALUES(4304,42,32,4304,'42:32','وَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4305,42,33,4305,'42:33','إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4306,42,34,4306,'42:34','أَوۡ يُوبِقۡهُنَّ بِمَا كَسَبُواْ وَيَعۡفُ عَن كَثِيرٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4307,42,35,4307,'42:35','وَيَعۡلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4308,42,36,4308,'42:36','فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4309,42,37,4309,'42:37','وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4310,42,38,4310,'42:38','وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4311,42,39,4311,'42:39','وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,423,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4312,42,40,4312,'42:40','وَجَزَـٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّـٰلِمِينَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,424,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4313,42,41,4313,'42:41','وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَـٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4314,42,42,4314,'42:42','إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4315,42,43,4315,'42:43','وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4316,42,44,4316,'42:44','وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيّٖ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّـٰلِمِينَ لَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدّٖ مِّن سَبِيلٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4317,42,45,4317,'42:45','وَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرۡفٍ خَفِيّٖۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّـٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4318,42,46,4318,'42:46','وَمَا كَانَ لَهُم مِّنۡ أَوۡلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4319,42,47,4319,'42:47','ٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4320,42,48,4320,'42:48','فَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ وَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4321,42,49,4321,'42:49','لِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,424,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4322,42,50,4322,'42:50','أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانٗا وَإِنَٰثٗاۖ وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمٞ قَدِيرٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,425,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4323,42,51,4323,'42:51','۞وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ رَسُولٗا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمٞ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22,NULL,0,'{}',NULL,425,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4324,42,52,4324,'42:52','وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27,NULL,0,'{}',NULL,425,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4325,42,53,4325,'42:53','صِرَٰطِ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ',NULL,NULL,10,73,292,NULL,NULL,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,425,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
