INSERT INTO verses VALUES(4328,43,3,4328,'43:3','إِنَّا جَعَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4329,43,4,4329,'43:4','وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4330,43,5,4330,'43:5','أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4331,43,6,4331,'43:6','وَكَمۡ أَرۡسَلۡنَا مِن نَّبِيّٖ فِي ٱلۡأَوَّلِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4332,43,7,4332,'43:7','وَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4333,43,8,4333,'43:8','فَأَهۡلَكۡنَآ أَشَدَّ مِنۡهُم بَطۡشٗا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4334,43,9,4334,'43:9','وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِيزُ ٱلۡعَلِيمُ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,430,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4335,43,10,4335,'43:10','ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَجَعَلَ لَكُمۡ فِيهَا سُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,431,1,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4336,43,11,4336,'43:11','وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4337,43,12,4337,'43:12','وَٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4338,43,13,4338,'43:13','لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
