INSERT INTO verses VALUES(4340,43,15,4340,'43:15','وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ مُّبِينٌ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4341,43,16,4341,'43:16','أَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَأَصۡفَىٰكُم بِٱلۡبَنِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4342,43,17,4342,'43:17','وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَٰنِ مَثَلٗا ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٌ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4343,43,18,4343,'43:18','أَوَمَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4344,43,19,4344,'43:19','وَجَعَلُواْ ٱلۡمَلَـٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ أَشَهِدُواْ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَٰدَتُهُمۡ وَيُسۡـَٔلُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,431,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4345,43,20,4345,'43:20','وَقَالُواْ لَوۡ شَآءَ ٱلرَّحۡمَٰنُ مَا عَبَدۡنَٰهُمۗ مَّا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَخۡرُصُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,432,2,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4346,43,21,4346,'43:21','أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4347,43,22,4347,'43:22','بَلۡ قَالُوٓاْ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4348,43,23,4348,'43:23','وَكَذَٰلِكَ مَآ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4349,43,24,4349,'43:24','۞قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4350,43,25,4350,'43:25','فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4351,43,26,4351,'43:26','وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4352,43,27,4352,'43:27','إِلَّا ٱلَّذِي فَطَرَنِي فَإِنَّهُۥ سَيَهۡدِينِ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4353,43,28,4353,'43:28','وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4354,43,29,4354,'43:29','بَلۡ مَتَّعۡتُ هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ جَآءَهُمُ ٱلۡحَقُّ وَرَسُولٞ مُّبِينٞ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,432,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4355,43,30,4355,'43:30','وَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,433,3,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4356,43,31,4356,'43:31','وَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4357,43,32,4357,'43:32','أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4358,43,33,4358,'43:33','وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4359,43,34,4359,'43:34','وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4360,43,35,4360,'43:35','وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4361,43,36,4361,'43:36','وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4362,43,37,4362,'43:37','وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4363,43,38,4363,'43:38','حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيۡتَ بَيۡنِي وَبَيۡنَكَ بُعۡدَ ٱلۡمَشۡرِقَيۡنِ فَبِئۡسَ ٱلۡقَرِينُ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4364,43,39,4364,'43:39','وَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,433,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4365,43,40,4365,'43:40','أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,434,4,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4366,43,41,4366,'43:41','فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4367,43,42,4367,'43:42','أَوۡ نُرِيَنَّكَ ٱلَّذِي وَعَدۡنَٰهُمۡ فَإِنَّا عَلَيۡهِم مُّقۡتَدِرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4368,43,43,4368,'43:43','فَٱسۡتَمۡسِكۡ بِٱلَّذِيٓ أُوحِيَ إِلَيۡكَۖ إِنَّكَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4369,43,44,4369,'43:44','وَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4370,43,45,4370,'43:45','وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَآ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَٰنِ ءَالِهَةٗ يُعۡبَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4371,43,46,4371,'43:46','وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4372,43,47,4372,'43:47','فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4373,43,48,4373,'43:48','وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4374,43,49,4374,'43:49','وَقَالُواْ يَـٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,434,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4375,43,50,4375,'43:50','فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,435,5,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4376,43,51,4376,'43:51','وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4377,43,52,4377,'43:52','أَمۡ أَنَا۠ خَيۡرٞ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينٞ وَلَا يَكَادُ يُبِينُ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4378,43,53,4378,'43:53','فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَـٰٓئِكَةُ مُقۡتَرِنِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4379,43,54,4379,'43:54','فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4380,43,55,4380,'43:55','فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4381,43,56,4381,'43:56','فَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4382,43,57,4382,'43:57','۞وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4383,43,58,4383,'43:58','وَقَالُوٓاْ ءَأَٰلِهَتُنَا خَيۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4384,43,59,4384,'43:59','إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلٗا لِّبَنِيٓ إِسۡرَـٰٓءِيلَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,435,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4385,43,60,4385,'43:60','وَلَوۡ نَشَآءُ لَجَعَلۡنَا مِنكُم مَّلَـٰٓئِكَةٗ فِي ٱلۡأَرۡضِ يَخۡلُفُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,436,6,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4386,43,61,4386,'43:61','وَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4387,43,62,4387,'43:62','وَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4388,43,63,4388,'43:63','وَلَمَّا جَآءَ عِيسَىٰ بِٱلۡبَيِّنَٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَيِّنَ لَكُم بَعۡضَ ٱلَّذِي تَخۡتَلِفُونَ فِيهِۖ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4389,43,64,4389,'43:64','إِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4390,43,65,4390,'43:65','فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ ظَلَمُواْ مِنۡ عَذَابِ يَوۡمٍ أَلِيمٍ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4391,43,66,4391,'43:66','هَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
INSERT INTO verses VALUES(4392,43,67,4392,'43:67','ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ',NULL,NULL,10,73,292,NULL,NULL,80,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,436,7,6,NULL,'{}','2025-12-21 16:16:08','2025-12-21 16:16:08');
