INSERT INTO verses VALUES(5437,71,18,5437,'71:18','ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,711,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5438,71,19,5438,'71:19','وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,711,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5439,71,20,5439,'71:20','لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,NULL,0,'{}',NULL,712,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5440,71,21,5440,'71:21','قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5441,71,22,5441,'71:22','وَمَكَرُواْ مَكۡرٗا كُبَّارٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5442,71,23,5442,'71:23','وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5443,71,24,5443,'71:24','وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَٰلٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5444,71,25,5444,'71:25','مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5445,71,26,5445,'71:26','وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5446,71,27,5446,'71:27','إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5447,71,28,5447,'71:28','رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارَۢا',NULL,NULL,15,113,452,NULL,NULL,222,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15,NULL,0,'{}',NULL,712,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5448,72,1,5448,'72:1','قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5449,72,2,5449,'72:2','يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5450,72,3,5450,'72:3','وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5451,72,4,5451,'72:4','وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5452,72,5,5452,'72:5','وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5453,72,6,5453,'72:6','وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5454,72,7,5454,'72:7','وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5455,72,8,5455,'72:8','وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5456,72,9,5456,'72:9','وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,720,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5457,72,10,5457,'72:10','وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,NULL,0,'{}',NULL,721,1,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5458,72,11,5458,'72:11','وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5459,72,12,5459,'72:12','وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5460,72,13,5460,'72:13','وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5461,72,14,5461,'72:14','وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَـٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5462,72,15,5462,'72:15','وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5463,72,16,5463,'72:16','وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5464,72,17,5464,'72:17','لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5465,72,18,5465,'72:18','وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5466,72,19,5466,'72:19','وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,0,'{}',NULL,721,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5467,72,20,5467,'72:20','قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,722,2,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5468,72,21,5468,'72:21','قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,NULL,0,'{}',NULL,722,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5469,72,22,5469,'72:22','قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,NULL,0,'{}',NULL,722,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5470,72,23,5470,'72:23','إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16,NULL,0,'{}',NULL,722,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5471,72,24,5471,'72:24','حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,722,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
INSERT INTO verses VALUES(5472,72,25,5472,'72:25','قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا',NULL,NULL,15,113,452,NULL,NULL,224,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,NULL,0,'{}',NULL,722,3,7,NULL,'{}','2025-12-21 16:16:11','2025-12-21 16:16:11');
